#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int height;
    int index;
} Rectangle;

static int compare_rectangles(const void *a, const void *b) {
    const Rectangle *ra = (const Rectangle *)a;
    const Rectangle *rb = (const Rectangle *)b;

    if (ra->height != rb->height) {
        return (ra->height < rb->height) - (ra->height > rb->height);
    }
    return (ra->index > rb->index) - (ra->index < rb->index);
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    Rectangle *rectangles = malloc((size_t)n * sizeof(Rectangle));
    char *active = calloc((size_t)n, sizeof(char));
    if (rectangles == NULL || active == NULL) {
        free(rectangles);
        free(active);
        return 0;
    }

    for (int i = 0; i < n; i++) {
        scanf("%d", &rectangles[i].height);
        rectangles[i].index = i;
    }

    qsort(rectangles, n, sizeof(Rectangle), compare_rectangles);

    int components = 0;
    int max_components = 0;

    for (int i = 0; i < n; ) {
        int j = i;
        while (j < n && rectangles[j].height == rectangles[i].height) {
            int pos = rectangles[j].index;
            active[pos] = 1;
            components++;

            if (pos > 0 && active[pos - 1]) {
                components--;
            }
            if (pos + 1 < n && active[pos + 1]) {
                components--;
            }
            j++;
        }

        if (components > max_components) {
            max_components = components;
        }
        i = j;
    }

    printf("%d\n", max_components + 1);

    free(rectangles);
    free(active);
    return 0;
}
